'use strict';
// Presentation layer over the independent tender workspaces.
const previousComparison=comparison,previousRequirements=requirements,previousDrafts=drafts,previousEvaluation=evaluation,previousBind=bindView,previousRender=render;
let chartMetric='cost',includeSample=true,selectedOffer='studio',showAllOffers=false,issueOnly=false;
let replayTimer=null,replayOwner=null,replayIndex=0;
const paymentPercent=o=>Number(o.advance.replace('%',''));
const offerCost=(o,extras=includeSample)=>o.total+(extras&&o.id==='print'?800:0);
const requirementChecks=o=>[
 {label:'Material',detail:o.material,level:o.id==='quick'?'fail':'pass',requirement:'Minimum 180 GSM cotton'},
 {label:'Delivery',detail:o.date+' 2026',level:['campus','quick'].includes(o.id)?'fail':'pass',requirement:'By 10 November'},
 {label:'Advance',detail:o.advance,level:o.id==='quick'?'fail':'pass',requirement:'40% maximum'},
 {label:'Printed sample',detail:o.sample,level:o.id==='print'?'tradeoff':o.id==='quick'?'unknown':'pass',requirement:'Preferred, not mandatory'},
 {label:'Packaging',detail:o.pack,level:o.pack==='Bulk'?'tradeoff':'pass',requirement:'Individual preferred; bulk allowed'}
];
function costExplanation(o){if(o.id==='studio')return 'Studio Merch costs ₹1,400 more than Print & Co. with its sample included. That premium buys individual packaging; both meet the essentials. Choose Print & Co. if packaging is not worth the extra spend.';if(o.id==='print')return 'The lowest eligible base price is ₹30,200. Its optional printed sample adds ₹800, taking the comparable total to ₹31,000. Bulk packaging is an allowed compromise. This is a strong choice when cost is the priority.';if(o.id==='thread')return 'Threadworks costs ₹2,100 more than Studio Merch. It offers 200 GSM fabric, delivery two days earlier, and a lower 25% advance. The extra spend makes sense only if those advantages matter to you.';if(o.id==='campus')return 'At ₹28,800, Campus Supply saves ₹3,600 against Studio Merch, but delivery is two days late. A low price cannot compensate for missing the event deadline. Ask for a revised delivery commitment before shortlisting.';return 'QuickPrint is cheapest at ₹27,000, but fails the material, delivery, and advance limits. It is not an eligible bargain under the current brief.';}
function chartMarkup(){const metric=chartMetric,items=sampleOffers,maximum=metric==='cost'?40000:100,limit=metric==='cost'?35000:40;return `<div class="chart-title"><div><h3>${metric==='cost'?'What will you actually pay?':'How much must you pay upfront?'}</h3><p>${metric==='cost'?'All five offers · base totals include tax and delivery':'Advance as a percentage of the quoted amount'}</p></div><span class="chart-unit">${metric==='cost'?'INR · ₹':'PERCENT · %'}</span></div><div class="chart-key"><span><i class="key-dot violet-key"></i>Eligible offer</span><span><i class="key-dot coral-key"></i>Fails a mandatory condition</span>${metric==='cost'?'<span><i class="key-dot gold-key"></i>Optional sample</span>':''}</div><div class="bar-chart" role="group" aria-label="${metric==='cost'?'Quotation price comparison in rupees':'Advance payment comparison in percent'}">${items.map(o=>{const base=metric==='cost'?o.total:paymentPercent(o);const extra=metric==='cost'&&includeSample&&o.id==='print'?800:0;const fail=o.rank>3;return `<button class="bar-row ${selectedOffer===o.id?'selected':''}" data-select-offer="${o.id}" aria-pressed="${selectedOffer===o.id}" aria-label="${esc(o.name)}: ${metric==='cost'?money(base+extra):base+' percent'}, ${esc(o.compliance)}"><span class="bar-label"><span>${o.name}</span><small>${o.rank<=3?'Shortlisted':o.id==='campus'?'Delivery mismatch':'3 mandatory mismatches'}</small></span><span class="bar-space"><span class="bar-limit" style="left:${limit/maximum*100}%"></span><span class="bar-main ${fail?'bar-fail':''}" style="width:${base/maximum*100}%"></span>${extra?`<span class="bar-extra" style="left:${base/maximum*100}%;width:${extra/maximum*100}%"></span>`:''}</span><strong>${metric==='cost'?money(base+extra):base+'%'}</strong></button>`}).join('')}<div class="chart-axis"><span></span><div><span>0</span><span>${metric==='cost'?'₹20k':'50%'}</span><span>${metric==='cost'?'₹40k':'100%'}</span></div><span></span></div></div><div class="chart-foot"><span class="limit-legend"></span>Your limit: ${metric==='cost'?'₹35,000 total':'40% advance'} · Select an offer to inspect the trade-off.</div>`;}
function selectedExplanation(){const o=sampleOffers.find(x=>x.id===selectedOffer)||sampleOffers[0];return `<div class="selected-insight ${o.rank>3?'has-mismatch':''}" aria-live="polite"><span class="supplier-icon ${o.colour}">${o.initial}</span><div><span class="eyebrow">${o.rank>3?'PRICE IS ONLY PART OF THE PICTURE':'VALUE, IN CONTEXT'}</span><h3>${o.name}</h3><p>${costExplanation(o)}</p><button class="source-link" data-evidence="${o.id}">Inspect quotation details ↗</button></div></div>`;}
comparison=function(){if(!hasCurrentAssessment())return previousComparison();return `${tenderHead()}<div class="agent-strip"><span class="agent-pulse"></span><span><strong>Sample evaluation ready</strong> · Five offers reviewed against your brief</span><button data-go="evaluation">View activity ↗</button></div><div class="visual-decision"><div><span class="eyebrow">A BETTER FIT, NOT JUST A LOWER NUMBER</span><h2>Your money. Your must-haves.<br><span>The trade-offs, made clear.</span></h2><p>Studio Merch covers your preferences. Print & Co. is the lower-cost eligible choice. The best choice depends on what the extras are worth to you.</p></div><div class="decision-stamp"><span>₹1,400</span><small>Studio’s premium over<br>Print & Co. with a sample</small><button data-guide="cost">Explain this to me ↗</button></div></div><section class="visual-chart-panel"><div class="chart-controls"><div class="segment" role="group" aria-label="Comparison metric"><button data-chart-metric="cost" class="${chartMetric==='cost'?'active':''}" aria-pressed="${chartMetric==='cost'}">Total cost</button><button data-chart-metric="advance" class="${chartMetric==='advance'?'active':''}" aria-pressed="${chartMetric==='advance'}">Advance payment</button></div><label class="switch-label"><input type="checkbox" id="include-sample" ${includeSample?'checked':''} ${chartMetric!=='cost'?'disabled':''}>Include optional printed sample</label></div><div id="chart-content">${chartMarkup()}</div>${selectedExplanation()}</section><div class="section-row checklist-heading"><div><h2>Does it meet your brief?</h2><p>Requirements remain in words. Every exception has a reason.</p></div><div class="checklist-tools"><label class="switch-label"><input id="issue-only" type="checkbox" ${issueOnly?'checked':''}>Only exceptions</label><button class="button small" data-toggle-all>${showAllOffers?'Top three only':'Include excluded offers'}</button></div></div><div class="requirement-cards">${(showAllOffers?sampleOffers:sampleOffers.slice(0,3)).map(o=>`<article class="requirement-card ${o.rank>3?'mismatch-card':''}"><div class="req-card-head"><span class="supplier-icon ${o.colour}">${o.initial}</span><div><h3>${o.name}</h3><span class="chip ${o.rank>3?'red':'violet'}">${o.rank>3?'Needs revision':o.label}</span></div></div>${requirementChecks(o).filter(c=>!issueOnly||c.level!=='pass').map(c=>`<div class="requirement-check ${c.level}"><span class="check-symbol">${c.level==='pass'?'✓':c.level==='fail'?'!':c.level==='unknown'?'?':'↔'}</span><div><strong>${c.label}<small>${c.level==='fail'?'Does not meet':c.level==='tradeoff'?'Allowed trade-off':c.level==='unknown'?'Needs clarification':'Meets'}</small></strong><p>${c.detail}</p><span>${c.requirement}</span></div></div>`).join('')||'<p class="all-clear">✓ No exceptions for this offer.</p>'}<div class="req-summary"><p>${o.note}</p>${o.id==='quick'?'<button class="button small" data-evidence="quick">Review mismatches ↗</button>':`<button class="button small" data-compose="${o.id}">${o.rank>3?'Request a revision':'Prepare next move'} ↗</button>`}</div></article>`).join('')}</div><div class="attention-callout"><span>!</span><div><h3>The cheapest quotation isn’t the cheapest usable offer.</h3><p>QuickPrint saves ₹5,400 against Studio Merch, but fails three mandatory conditions. Campus Supply could still work if its delivery moves from 12 to 10 November.</p></div><button data-compose="campus">Ask Campus Supply ↗</button></div>${foot()}`;};
const extraFields=[['success','What would a successful outcome look like?','Describe the experience, quality, and result you want—not just the item.'],['context','What should the agent know about this purchase?','Why are you buying? Who will use it? What went wrong last time?'],['scope','What must the supplier include?','Installation, staff, transport, support, documentation, or other scope.'],['acceptance','How will you check or accept the work?','Sample approval, inspection, testing, milestones, sign-off…'],['risks','What should the agent watch out for?','Hidden charges, vague specifications, unrealistic dates, exclusions…'],['agentPrompt','Your instructions to the agent','For example: focus on delivery certainty; explain any cost premium; ask before relaxing specifications.']];
requirements=function(){let html=previousRequirements();const b=state.brief;const fields=`<div class="brief-chapter"><span>02</span><div><h2>Give the agent your context.</h2><p>Good judgment starts with knowing what matters to you.</p></div></div>${extraFields.map(([key,label,placeholder])=>`<div class="field"><label for="brief-${key}">${label}</label><textarea id="brief-${key}" name="${key}" placeholder="${placeholder}">${esc(b[key]||'')}</textarea></div>`).join('')}<div class="brief-chapter"><span>03</span><div><h2>Choose how we work together.</h2><p>These preferences are saved with this tender.</p></div></div><div class="field-row"><div class="field"><label for="brief-mode">Working style</label><select id="brief-mode" name="workingStyle">${['Guide me step by step','Let me explore the details','Give me the concise recommendation'].map(x=>`<option ${b.workingStyle===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="brief-autonomy">Agent permissions</label><select id="brief-autonomy" name="agentPermissions">${['Analyse and draft only','Suggest follow-ups for approval'].map(x=>`<option ${b.agentPermissions===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label for="brief-tone">Email tone</label><select id="brief-tone" name="tone">${['Professional and friendly','Concise and direct','Formal procurement'].map(x=>`<option ${b.tone===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="brief-submission">Quotation submission deadline</label><input id="brief-submission" name="submissionDate" type="date" value="${esc(b.submissionDate||'')}"></div></div><p class="preference-note">Saved for this tender. Live agent behaviour will use these settings when connected. Your draft messages remain editable.</p>`;return html.replace('<div id="brief-error"',fields+'<div id="brief-error"');};
const activityEvents=[['INFO','brief.loaded','Loaded the sample brief and buyer priorities.'],['INFO','offers.reviewed','Reviewed five illustrative supplier records.'],['CHECK','terms.checked','Checked material, deadline, payment, and optional extras.'],['WARN','delivery.mismatch','Campus Supply proposes 12 Nov; required by 10 Nov.'],['WARN','requirements.failed','QuickPrint fails material, deadline, and advance limits.'],['CALC','totals.normalised','Print & Co.: ₹30,200 + ₹800 optional sample = ₹31,000.'],['RESULT','shortlist.ready','Three offers meet the mandatory conditions.'],['DRAFT','followups.prepared','Prepared three shortlisted follow-ups and one delivery revision.'],['WAIT','buyer.review','Waiting for buyer review. No emails sent.']];
function visibleActivity(){if(replayOwner===activeId&&replayTimer)return activityEvents.slice(0,replayIndex);return activityEvents;}
evaluation=function(){if(!hasCurrentAssessment())return localActivityPage();const playing=!!replayTimer&&replayOwner===activeId;return `${tenderHead()}<div class="section-row activity-heading"><div><span class="eyebrow">AGENT ACTIVITY</span><h2>A clear view of what happened.</h2><p>Operational events, checks, and results. Expand an event for its context.</p></div><button class="button small" data-replay ${playing?'disabled':''}>${playing?'Replaying…':'Replay sample run ↻'}</button></div><div class="activity-console"><div class="console-top"><span><span class="console-dot"></span>quotelens / ${esc(state.id)}</span><span class="chip ${playing?'gold':'neutral'}">${playing?'DEMO REPLAY':'SAMPLE EVENTS'}</span></div><div class="console-lines" id="console-lines">${activityLines()}</div><div class="console-bottom"><span>${playing?'Replaying prepared events':'Paused at buyer review'}</span><span>Live backend not connected</span></div></div>${localActivityPanel()}<div class="activity-context"><h3>What the log tells you</h3><p>Which documents were reviewed, what mismatched, how totals were calculated, and what needs your attention. In the live product these events will stream from the worker, with secrets and document contents excluded from raw logs.</p><button class="button small primary" data-go="comparison">Explore the comparison ↗</button></div>`;};
function localActivityPanel(){const events=state.activity||[];return `<section class="local-activity"><div class="section-row"><h2>Actual workspace activity</h2><span>Browser events · This tender only</span></div><div class="activity-console"><div class="console-lines">${events.length?events.slice(-30).map(e=>`<div class="local-event"><time>${esc(new Date(e.at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}))}</time><code>${esc(e.event)}</code><p>${esc(e.message)}</p></div>`).join(''):'<p class="console-wait">No local actions recorded yet.</p>'}</div></div></section>`;}
function localActivityPage(){return `${tenderHead()}<div class="activity-heading"><span class="eyebrow">AGENT ACTIVITY</span><h2>Your workspace, as it happens.</h2><p>These are actual browser actions for this tender. Model and email services are not connected yet.</p></div>${localActivityPanel()}<div class="activity-context"><p>${state.stale?'The brief has changed; the previous assessment is no longer current.':'Upload supplier quotations and save your brief to prepare for evaluation.'}</p><button class="button small" data-go="quotations">Go to quotations →</button></div>`;}
function activityLines(){return visibleActivity().map((e,i)=>`<details class="console-line ${e[0]==='WARN'?'warn':''}"><summary><time>+00:${String(i*2).padStart(2,'0')}</time><b>${e[0]}</b><code>${e[1]}</code><span>${e[2]}</span></summary><p>${e[1]==='delivery.mismatch'?'Sample source: campus-supply-offer.pdf · delivery field: 12 Nov. Buyer brief: 10 Nov. A two-day mismatch blocks eligibility.':e[1]==='totals.normalised'?'The ₹800 sample is optional. Including it makes Print & Co. ₹1,400 cheaper than Studio Merch; packaging remains a trade-off.':'Prepared sample event. Actions are scoped to this tender; no live model or email action occurred.'}</p></details>`).join('')||'<p class="console-wait">Starting the sample replay…</p>';}
function replayActivity(){clearInterval(replayTimer);replayOwner=activeId;replayIndex=0;replayTimer=setInterval(()=>{replayIndex++;if(replayIndex>=activityEvents.length){clearInterval(replayTimer);replayTimer=null;}if(view==='evaluation'&&activeId===replayOwner)render();},650);render();}
drafts=function(){if(!hasCurrentAssessment())return previousDrafts();return `${tenderHead()}<div class="section-row draft-hub-heading"><div><span class="eyebrow">YOUR NEXT CONVERSATION</span><h2>A considered next move for every offer.</h2><p>Review the goal, open the draft, and make it sound like you.</p></div><button class="button small" data-action="email-connect">Connect email ↗</button></div><div class="draft-hub">${sampleOffers.slice(0,4).map(o=>`<article class="draft-hub-card"><div class="draft-hub-top"><span class="supplier-icon ${o.colour}">${o.initial}</span><div><h3>${o.name}</h3><span>${state.drafts[o.id]?'Saved draft':'Prepared sample draft'}</span></div><span class="chip ${o.rank>3?'gold':'violet'}">${o.rank>3?'Potential offer':'Shortlisted'}</span></div><h4>${o.id==='campus'?'Can they meet your deadline?':o.id==='print'?'Include the sample in the price.':'A better price, with the same scope.'}</h4><p>${o.note}</p><div class="draft-hub-bottom"><span>✉ ${o.contact}</span><button class="button small primary" data-compose="${o.id}">Open draft ↗</button></div></article>`).join('')}</div><div class="page-foot"><span>Nothing is sent automatically. Recipients and terms stay under your control.</span><span>4 prepared sample drafts</span></div>`;};
function composeEmail(id){const o=sampleOffers.find(x=>x.id===id);if(!o||!hasCurrentAssessment())return;selectedDraft=id;const owner=state;const d=owner.drafts[id]||{email:o.email,subject:'Revised quotation request — '+owner.brief.name,body:`Hi ${o.contact},\n\n${o.draft}\n\nRegards,\nTechSpace team`};modal('A better next conversation.',`<form id="compose-form"><div class="composer-supplier"><span class="supplier-icon ${o.colour}">${o.initial}</span><div><strong>${o.name}</strong><span>${o.rank>3?'Resolve the delivery mismatch':'Negotiate without changing the essentials'}</span></div><span class="chip gold">Draft only</span></div><div class="email-meta"><span>To</span><input type="email" name="email" required aria-label="Recipient" value="${esc(d.email)}"></div><div class="email-meta"><span>Subject</span><input name="subject" required aria-label="Subject" value="${esc(d.subject)}"></div><label class="visually-hidden" for="composer-body">Email message</label><textarea id="composer-body" class="email-body" name="body" required>${esc(d.body)}</textarea><div class="composer-context"><span>KEEP IN THE MESSAGE</span><p>Quantity, mandatory specifications, delivery date, and approved payment limits. Ask for written revised terms.</p></div><div class="composer-footer"><span id="composer-save-status">Edits save locally as you type.</span><div><button class="button small" type="button" data-composer-copy>Copy draft</button><button class="button small primary" type="submit">Save & close</button></div></div></form>`);$('.modal').classList.add('composer-modal');const form=$('#compose-form');let saved=true;const save=()=>{owner.drafts[id]=Object.fromEntries(new FormData(form));saved=persist();$('#composer-save-status').textContent=saved?'Saved locally · No email sent':'Could not save locally. Copy to keep your edits.';};form.addEventListener('input',save);form.addEventListener('submit',e=>{e.preventDefault();save();if(saved){(owner.activity??=[]).push({at:new Date().toISOString(),level:'DRAFT',event:'draft.saved',message:'Saved an editable supplier follow-up. No email sent.'});persist();closeModal();if(view==='drafts')render();toast('Draft saved. No email sent.')}});form.querySelector('[data-composer-copy]').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(form.elements.body.value);toast('Draft copied.')}catch{form.elements.body.select();toast('Select and copy the draft manually.')}});}
bindView=function(){previousBind();$('#include-sample')?.addEventListener('change',e=>{includeSample=e.target.checked;render()});$('#issue-only')?.addEventListener('change',e=>{issueOnly=e.target.checked;render()});};
render=function(){previousRender();document.querySelector('[data-go="evaluation"]')?.setAttribute('aria-label','Agent activity');window.dispatchEvent(new CustomEvent('quotelens:view',{detail:{view}}));};
window.getQuoteLensContext=()=>({view,hasAssessment:hasCurrentAssessment(),title:state.brief.name});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.chartMetric){chartMetric=b.dataset.chartMetric;render()}if(b.dataset.selectOffer){selectedOffer=b.dataset.selectOffer;render()}if(b.hasAttribute('data-toggle-all')){showAllOffers=!showAllOffers;render()}if(b.dataset.compose)composeEmail(b.dataset.compose);if(b.hasAttribute('data-replay'))replayActivity();});
render();
